1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	
17	interface LedgerEntry {
18	  seq: number; // 全局流水序号，即提交顺序
19	  doc: string; // 单据编号
20	  type: DocType;
21	  product: string;
22	  wh: string; // 本流水条目变动余量的仓库
23	  qty: number; // 恒为正数，方向由 type / 出入仓决定
24	  before: number;
25	  after: number;
26	  from?: string; // 调拨单的调出仓
27	  to?: string; // 调拨单的调入仓
28	}
29	
30	interface DocRecord {
31	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
32	  resultLines: string[]; // 原提交结果，供幂等重放
33	}
34	
35	interface Store {
36	  version: 1;
37	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写）
38	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
39	  entries: LedgerEntry[];
40	  docs: Record<string, DocRecord>;
41	}
42	
43	function emptyStore(): Store {
44	  return { version: 1, products: {}, stock: {}, entries: [], docs: {} };
45	}
46	
47	// ---------- 工具 ----------
48	
49	function isPlainObject(v: unknown): v is Record<string, unknown> {
50	  return typeof v === 'object' && v !== null && !Array.isArray(v);
51	}
52	
53	function isNonNegSafeInt(v: unknown): v is number {
54	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
55	}
56	
57	function isPosSafeInt(v: unknown): v is number {
58	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
59	}
60	
61	function trimOrThrow(label: string, raw: string): string {
62	  const s = raw.trim();
63	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
64	  return s;
65	}
66	
67	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
68	function stableStringify(v: unknown): string {
69	  if (isPlainObject(v)) {
70	    return (
71	      '{' +
72	      Object.keys(v)
73	        .sort()
74	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
75	        .join(',') +
76	      '}'
77	    );
78	  }
79	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
80	  return JSON.stringify(v);
81	}
82	
83	// ---------- 数据持久化 ----------
84	
85	function dataPath(dataDir: string): string {
86	  return join(dataDir, DATA_FILENAME);
87	}
88	
89	function loadStore(dataDir: string): Store {
90	  let raw: string;
91	  try {
92	    raw = readFileSync(dataPath(dataDir), 'utf8');
93	  } catch (e) {
94	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
95	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
96	  }
97	
98	  let data: unknown;
99	  try {
100	    data = JSON.parse(raw);
101	  } catch {
102	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
103	  }
104	  return validateStore(data);
105	}
106	
107	function validateStore(data: unknown): Store {
108	  const bad = (msg: string): DataError =>
109	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
110	
111	  if (!isPlainObject(data)) throw bad('根节点不是对象');
112	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
113	
114	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
115	  for (const [id, name] of Object.entries(data.products)) {
116	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
117	      throw bad('products 中存在非法编号或名称');
118	  }
119	
120	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
121	  for (const [pid, whs] of Object.entries(data.stock)) {
122	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
123	    for (const [wh, qty] of Object.entries(whs)) {
124	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
125	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
126	    }
127	  }
128	
129	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
130	  let lastSeq = 0;
131	  for (const e of data.entries as unknown[]) {
132	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
133	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
134	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
135	    if (e.type !== 'in' && e.type !== 'out' && e.type !== 'transfer') throw bad('流水类型非法');
136	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
137	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
138	    if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
139	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
140	    if (e.type === 'transfer') {
141	      if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
142	        throw bad('调拨流水缺少调出/调入仓');
143	    }
144	  }
145	
146	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
147	  for (const [docId, rec] of Object.entries(data.docs)) {
148	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
149	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
150	      throw bad(`单据 ${docId} 的去重记录非法`);
151	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
152	  }
153	
154	  return data as unknown as Store;
155	}
156	
157	function saveStore(dataDir: string, store: Store): void {
158	  const path = dataPath(dataDir);
159	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
160	  try {
161	    mkdirSync(dataDir, { recursive: true });
162	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
163	    renameSync(tmp, path);
164	  } catch (e) {
165	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
166	  }
167	}
168	
169	// ---------- 参数解析 ----------
170	
171	interface ParsedArgs {
172	  positionals: string[];
173	  flags: Record<string, string>;
174	  multi: Record<string, string[]>;
175	}
176	
177	function parseArgs(
178	  tokens: string[],
179	  singles: string[],
180	  multis: string[] = [],
181	): ParsedArgs {
182	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
183	  const singleSet = new Set(singles);
184	  const multiSet = new Set(multis);
185	
186	  for (let i = 0; i < tokens.length; i++) {
187	    const tok = tokens[i];
188	    if (tok.startsWith('--')) {
189	      let key = tok;
190	      let value: string | undefined;
191	      const eq = tok.indexOf('=');
192	      if (eq >= 0) {
193	        key = tok.slice(0, eq);
194	        value = tok.slice(eq + 1);
195	      }
196	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
197	      if (value === undefined) {
198	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
199	        value = tokens[++i];
200	      }
201	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
202	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
203	      else out.flags[key] = value;
204	    } else {
205	      out.positionals.push(tok);
206	    }
207	  }
208	  return out;
209	}
210	
211	function parseItem(raw: string, merged: Map<string, number>): void {
212	  const idx = raw.indexOf(':');
213	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
214	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
215	  const qtyRaw = raw.slice(idx + 1).trim();
216	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
217	  const qty = Number(qtyRaw);
218	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
219	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
220	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
221	  merged.set(pid, sum);
222	}
223	
224	interface DocRequest {
225	  type: DocType;
226	  docId: string;
227	  wh?: string;
228	  from?: string;
229	  to?: string;
230	  items: Map<string, number>;
231	}
232	
233	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
234	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
235	  const docId = args.positionals[0];
236	  if (docId === undefined || args.positionals.length !== 1)
237	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
238	
239	  const items = new Map<string, number>();
240	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
241	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
242	
243	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
244	  if (type === 'transfer') {
245	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
246	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
247	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
248	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
249	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
250	  } else {
251	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
252	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
253	  }
254	  return req;
255	}
256	
257	// ---------- 业务核心 ----------
258	
259	const MAX_SAFE = Number.MAX_SAFE_INTEGER;
260	
261	function canonicalContent(req: DocRequest): Record<string, unknown> {
262	  const items: Record<string, number> = {};
263	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
264	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
265	  return { type: req.type, wh: req.wh!, items };
266	}
267	
268	function getStock(stock: Store['stock'], pid: string, wh: string): number {
269	  return stock[pid]?.[wh] ?? 0;
270	}
271	
272	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
273	  (stock[pid] ??= {})[wh] = qty;
274	}
275	
276	interface SubmitOutcome {
277	  duplicate: boolean;
278	  lines: string[];
279	}
280	
281	/** 整单先校验、模拟，全部合法后才一次性落库；任一明细失败则全部保持原状。 */
282	function submitDocument(dataDir: string, store: Store, req: DocRequest): SubmitOutcome {
283	  const content = canonicalContent(req);
284	  const existed = store.docs[req.docId];
285	  if (existed !== undefined) {
286	    if (stableStringify(existed.content) !== stableStringify(content))
287	      throw new BizError(`单据编号 ${req.docId} 已用于业务内容不同的单据，拒绝提交`);
288	    return { duplicate: true, lines: existed.resultLines }; // 幂等：返回原结果，不动库存
289	  }
290	
291	  for (const pid of req.items.keys()) {
292	    if (store.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
293	  }
294	
295	  const draft: Store['stock'] = structuredClone(store.stock);
296	  const additions: LedgerEntry[] = [];
297	  const reportLines: string[] = [];
298	  let seq = store.entries.length;
299	  const typeLabel = req.type === 'in' ? '入库' : req.type === 'out' ? '出库' : '调拨';
300	
301	  for (const pid of [...req.items.keys()].sort()) {
302	    const qty = req.items.get(pid)!;
303	
304	    if (req.type === 'in') {
305	      const wh = req.wh!;
306	      const before = getStock(draft, pid, wh);
307	      const after = before + qty;
308	      if (after > MAX_SAFE) throw new BizError(`商品 ${pid} 入库后余量超出安全整数范围，拒绝整单`);
309	      setStock(draft, pid, wh, after);
310	      additions.push({ seq: ++seq, doc: req.docId, type: 'in', product: pid, wh, qty, before, after });
311	      reportLines.push(`入库 ${pid} @${wh} +${qty}：${before} -> ${after}`);
312	    } else if (req.type === 'out') {
313	      const wh = req.wh!;
314	      const before = getStock(draft, pid, wh);
315	      if (before < qty)
316	        throw new BizError(`商品 ${pid} 仓库 ${wh} 余量不足（当前 ${before}，需出库 ${qty}），拒绝整单`);
317	      const after = before - qty;
318	      setStock(draft, pid, wh, after);
319	      additions.push({ seq: ++seq, doc: req.docId, type: 'out', product: pid, wh, qty, before, after });
320	      reportLines.push(`出库 ${pid} @${wh} -${qty}：${before} -> ${after}`);
321	    } else {
322	      const from = req.from!;
323	      const to = req.to!;
324	      const beforeFrom = getStock(draft, pid, from);
325	      if (beforeFrom < qty)
326	        throw new BizError(`商品 ${pid} 调出仓 ${from} 余量不足（当前 ${beforeFrom}，需调拨 ${qty}），拒绝整单`);
327	      const afterFrom = beforeFrom - qty;
328	      const beforeTo = getStock(draft, pid, to);
329	      const afterTo = beforeTo + qty;
330	      if (afterTo > MAX_SAFE) throw new BizError(`商品 ${pid} 调入后余量超出安全整数范围，拒绝整单`);
331	      setStock(draft, pid, from, afterFrom);
332	      setStock(draft, pid, to, afterTo);
333	      additions.push({
334	        seq: ++seq, doc: req.docId, type: 'transfer', product: pid, wh: from,
335	        qty, before: beforeFrom, after: afterFrom, from, to,
336	      });
337	      additions.push({
338	        seq: ++seq, doc: req.docId, type: 'transfer', product: pid, wh: to,
339	        qty, before: beforeTo, after: afterTo, from, to,
340	      });
341	      reportLines.push(
342	        `调拨 ${pid} ${from} -> ${to} ${qty}：${from} ${beforeFrom}->${afterFrom}；${to} ${beforeTo}->${afterTo}`,
343	      );
344	    }
345	  }
346	
347	  // 全部明细合法：一次性提交并在保存成功后才算成功
348	  store.stock = draft;
349	  store.entries.push(...additions);
350	  store.docs[req.docId] = { content, resultLines: reportLines };
351	  saveStore(dataDir, store);
352	
353	  return {
354	    duplicate: false,
355	    lines: [`${typeLabel}单 ${req.docId} 提交成功，共 ${req.items.size} 种商品：`, ...reportLines],
356	  };
357	}
358	
359	// ---------- 各命令处理 ----------
360	
361	function runProduct(rest: string[], dataDir: string, store: Store): void {
362	  const sub = rest[0];
363	  const tokens = rest.slice(1);
364	  if (sub === 'add') {
365	    const args = parseArgs(tokens, []);
366	    const [idRaw, nameRaw, ...extra] = args.positionals;
367	    if (idRaw === undefined || nameRaw === undefined || extra.length > 0)
368	      throw new UsageError('用法：product add <商品编号> <商品名称>');
369	    const id = trimOrThrow('商品编号', idRaw);
370	    const name = trimOrThrow('商品名称', nameRaw);
371	    if (store.products[id] !== undefined)
372	      throw new BizError(`商品编号 ${id} 已存在（${store.products[id]}），拒绝重复登记且不覆盖原资料`);
373	    store.products[id] = name;
374	    saveStore(dataDir, store);
375	    console.log(`已登记商品：${id}\t${name}`);
376	  } else if (sub === 'list' || sub === 'ls') {
377	    const args = parseArgs(tokens, []);
378	    if (args.positionals.length > 0) throw new UsageError('用法：product list');
379	    const ids = Object.keys(store.products).sort();
380	    console.log(`已登记商品（${ids.length}）：`);
381	    if (ids.length === 0) {
382	      console.log('（暂无已登记商品）');
383	    } else {
384	      console.log('编号\t名称');
385	      for (const id of ids) console.log(`${id}\t${store.products[id]}`);
386	    }
387	  } else {
388	    throw new UsageError(sub === undefined ? '用法：product <add|list> …' : `未知 product 子命令：${sub}`);
389	  }
390	}
391	
392	function runBalance(rest: string[], store: Store): void {
393	  const args = parseArgs(rest, ['--wh']);
394	  const [pidRaw, ...extra] = args.positionals;
395	  if (pidRaw === undefined || extra.length > 0) throw new UsageError('用法：balance <商品编号> [--wh <仓库>]');
396	  const pid = trimOrThrow('商品编号', pidRaw);
397	
398	  if (args.flags['--wh'] !== undefined) {
399	    const wh = trimOrThrow('仓库标识', args.flags['--wh']);
400	    const qty = getStock(store.stock, pid, wh); // 未发生变动的组合余量为 0
401	    console.log(`余量：商品 ${pid} 仓库 ${wh} = ${qty}`);
402	    return;
403	  }
404	
405	  const map = store.stock[pid] ?? {};
406	  const whs = Object.keys(map).filter((w) => map[w] !== 0).sort();
407	  if (whs.length === 0) {
408	    console.log(`商品 ${pid} 在各仓库余量均为 0`);
409	    return;
410	  }
411	  console.log(`商品 ${pid} 各仓余量：`);
412	  let total = 0;
413	  for (const wh of whs) {
414	    console.log(`仓库 ${wh}：${map[wh]}`);
415	    total += map[wh];
416	  }
417	  console.log(`合计：${total}`);
418	}
419	
420	const TYPE_LABEL: Record<DocType, string> = { in: '入库', out: '出库', transfer: '调拨' };
421	
422	function formatEntry(e: LedgerEntry): string {
423	  let signed: string;
424	  if (e.type === 'in') signed = `+${e.qty}`;
425	  else if (e.type === 'out') signed = `-${e.qty}`;
426	  else signed = `${e.wh === e.to ? '+' : '-'}${e.qty}`;
427	  let line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
428	  if (e.type === 'transfer') line += `\t调拨=${e.from}->${e.to}`;
429	  return line;
430	}
431	
432	function runFlow(rest: string[], store: Store): void {
433	  const args = parseArgs(rest, ['--product', '--wh']);
434	  if (args.positionals.length > 0) throw new UsageError('用法：flow (--product <商品编号> | --wh <仓库>)…');
435	  const product = args.flags['--product'];
436	  const wh = args.flags['--wh'];
437	  if (product === undefined && wh === undefined)
438	    throw new UsageError('flow 至少需要一个过滤条件：--product <商品编号> 和/或 --wh <仓库>');
439	  const pid = product === undefined ? undefined : trimOrThrow('商品编号', product);
440	  const wid = wh === undefined ? undefined : trimOrThrow('仓库标识', wh);
441	
442	  const rows = store.entries.filter(
443	    (e) => (pid === undefined || e.product === pid) && (wid === undefined || e.wh === wid),
444	  );
445	  const scope = [pid !== undefined ? `商品=${pid}` : null, wid !== undefined ? `仓库=${wid}` : null]
446	    .filter(Boolean)
447	    .join(' ');
448	  console.log(`流水（${scope}），共 ${rows.length} 条，按提交顺序：`);
449	  if (rows.length === 0) console.log('（无匹配流水）');
450	  else for (const e of rows) console.log(formatEntry(e));
451	}
452	
453	// ---------- 帮助与入口 ----------
454	
455	const HELP = `${APP_NAME} —— 本地多仓库存台账
456	
457	用法：
458	  node app.ts [-d, --data <数据目录>] <命令> [参数]
459	
460	全局选项：
461	  -d, --data <目录>   数据目录（默认 ./.stockroom）；不同目录的数据互不影响
462	
463	命令：
464	  product add <编号> <名称>                 登记商品（编号唯一、区分大小写，去空白后不能为空）
465	  product list                              列出已登记商品
466	  in <单据编号> --wh <仓库> --item <编号:数量> [...]       入库
467	  out <单据编号> --wh <仓库> --item <编号:数量> [...]      出库（余量不足整单拒绝）
468	  transfer <单据编号> --from <源仓> --to <目标仓> \\
469	           --item <编号:数量> [...]                        跨仓调拨（两仓不能相同）
470	  balance <商品编号> [--wh <仓库>]           查询余量；省略 --wh 查询各仓
471	  flow --product <编号> [--wh <仓库>]        按商品/仓库查询流水（至少一个过滤条件）
472	       | --wh <仓库> [--product <编号>]
473	  -h, --help                                显示本帮助
474	
475	规则：
476	  数量必须为正安全整数；同单同商品的重复明细先合并，再做足量与溢出校验；
477	  任一明细不合法则整单拒绝。单据编号在同一数据目录内全局唯一，相同内容重复
478	  提交返回原结果且不重复变动，同编号不同内容拒绝；失败提交不占用编号。
479	
480	示例：
481	  node app.ts -d ./data product add P1 螺丝
482	  node app.ts -d ./data in D1 --wh W1 --item P1:10 --item P2:3
483	  node app.ts -d ./data out D2 --wh W1 --item P1:4
484	  node app.ts -d ./data transfer D3 --from W1 --to W2 --item P1:2 --item P1:3
485	  node app.ts -d ./data balance P1
486	  node app.ts -d ./data balance P1 --wh W1
487	  node app.ts -d ./data flow --product P1
488	  node app.ts -d ./data flow --wh W2`;
489	
490	function printHelp(): void {
491	  console.log(HELP);
492	}
493	
494	function run(argv: string[]): void {
495	  // 先抽出全局 -d/--data，其余按命令解析
496	  let dataDir = DEFAULT_DATA_DIR;
497	  const rest: string[] = [];
498	  for (let i = 0; i < argv.length; i++) {
499	    const t = argv[i];
500	    if (t === '-d' || t === '--data') {
501	      if (i + 1 >= argv.length) throw new UsageError(`参数 ${t} 缺少数据目录取值`);
502	      dataDir = argv[++i];
503	    } else if (t.startsWith('--data=')) {
504	      dataDir = t.slice('--data='.length);
505	    } else {
506	      rest.push(t);
507	    }
508	  }
509	
510	  if (rest.length === 0) {
511	    printHelp();
512	    return;
513	  }
514	  const cmd = rest[0];
515	  if ((cmd === '-h' || cmd === '--help') && rest.length === 1) {
516	    printHelp();
517	    return;
518	  }
519	
520	  const tokens = rest.slice(1);
521	  switch (cmd) {
522	    case 'product': {
523	      const store = loadStore(dataDir);
524	      runProduct(tokens, dataDir, store);
525	      break;
526	    }
527	    case 'in':
528	    case 'out':
529	    case 'transfer': {
530	      const req = parseDocArgs(cmd, tokens);
531	      const store = loadStore(dataDir);
532	      const outcome = submitDocument(dataDir, store, req);
533	      if (outcome.duplicate) {
534	        console.log(`单据 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
535	      }
536	      for (const line of outcome.lines) console.log(line);
537	      break;
538	    }
539	    case 'balance': {
540	      const store = loadStore(dataDir);
541	      runBalance(tokens, store);
542	      break;
543	    }
544	    case 'flow': {
545	      const store = loadStore(dataDir);
546	      runFlow(tokens, store);
547	      break;
548	    }
549	    default:
550	      throw new UsageError(`未知命令：${cmd}（使用 --help 查看可用命令）`);
551	  }
552	}
553	
554	try {
555	  run(process.argv.slice(2));
556	} catch (e) {
557	  if (e instanceof UsageError) {
558	    console.error(`${APP_NAME}: ${e.message}`);
559	    process.exit(2);
560	  }
561	  if (e instanceof BizError || e instanceof DataError) {
562	    console.error(`${APP_NAME}: ${e.message}`);
563	    process.exit(1);
564	  }
565	  console.error(`${APP_NAME}: 发生未预期错误：${(e as Error)?.stack ?? String(e)}`);
566	  process.exit(1);
567	}
