      if (after > MAX_SAFE) throw new BizError(`冲销出库：商品 ${pid} 仓库 ${wh} 补回后余量超出安全整数范围，整单拒绝`);
      setStock(draft, pid, wh, after);
      additions.push({...});
      reportLines.push(`冲销出库 ${pid} @${wh} +${qty}：${before} -> ${after}`);
    } else {
      const from = oc.from; const to = oc.to;
      const beforeTo = getStock(draft, pid, to);
      if (beforeTo < qty) throw new BizError(`冲销调拨：商品 ${pid} 调入仓 ${to} 余量不足（当前 ${beforeTo}，需扣回 ${qty}），整单拒绝`);
      const afterTo = beforeTo - qty;
      const beforeFrom = getStock(draft, pid, from);
      const afterFrom = beforeFrom + qty;
      if (afterFrom > MAX_SAFE) throw new BizError(`冲销调拨：商品 ${pid} 调出仓 ${from} 补回后余量超出安全整数范围，整单拒绝`);
      setStock(draft, pid, to, afterTo);
      setStock(draft, pid, from, afterFrom);
      additions.push({seq: ++seq, doc: req.docId, type: 'reversal', product: pid, wh: to, qty, before: beforeTo, after: afterTo, from, to, ref: req.of});
      additions.push({seq: ++seq, doc: req.docId, type: 'reversal', product: pid, wh: from, qty, before: beforeFrom, after: afterFrom, from, to, ref: req.of});
      reportLines.push(`冲销调拨 ${pid} ${to} -> ${from} ${qty}：${to} ${beforeTo}->${afterTo}；${from} ${beforeFrom}->${afterFrom}`);
    }
  }

  store.stock = draft;
  store.entries.push(...additions);
  store.docs[req.docId] = { content, resultLines: reportLines };
  orig.reversedBy = req.docId;
  saveStore(dataDir, store);

  return { duplicate: false, lines: [`冲销单 ${req.docId} 提交成功，已冲销${typeLabel}单 ${req.of}，共 ${Object.keys(items).length} 种商品：`, ...reportLines] };
}
