  else signed = `${e.wh === e.to ? '+' : '-'}${e.qty}`;
  let line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
